// Assemble the Module 4 output envelope (schema: proposal-assembly.schema.json).
const cf = $('Compute Proposal Fields').first().json;
const art = $('Collect Artifacts').first().json;
let draftId = null;
try { draftId = $('Create Draft').first().json.id || $('Create Draft').first().json.message?.id || null; } catch (e) {}
// 'Send Draft' only runs on the send branch; referencing an unexecuted node throws, so the catch
// means 'send_mode was draft'. A genuine send failure fails that node and the run never reaches
// here — so 'sent:false' always means 'deliberately not sent', never 'silently lost'.
let sent_message_id = null;
try { sent_message_id = $('Send Draft').first().json.id || null; } catch (e) {}
return [{ json: {
  client_id: cf.client_id,
  status: 'ok',
  errors: [],
  data: {
    proposal_number: cf.proposal_number,
    document_id: art.document_id,
    document_url: art.document_url,
    docx_file_name: cf.docx_file_name,
    pdf_file_name: cf.pdf_file_name,
